CREATE TABLE t0(a TEXT,b TEXT,c TEXT); CREATE TABLE t1(a TEXT); INSERT INTO t1 VALUES('1'); CREATE VIEW v0 AS SELECT 'xyz' AS d; CREATE TABLE sfi_r1 AS SELECT * FROM v0 RIGHT JOIN t1 ON t1.a<>'' INNER JOIN t0 ON t0.c<>''; CREATE TABLE sfi_r2 AS SELECT * FROM v0 RIGHT JOIN t1 ON t1.a<>'' INNER JOIN t0 ON t0.c<>'' WHERE b ISNULL;